using System.Text.Json;

namespace TutorFlow.Api;

public record Usuario(string Rol, string Id, string Nombre, string Programa);

// Única clase que conoce el formato de los JSON de datos. Cada registro se clasifica por su forma.
public class Datos
{
    public IReadOnlyList<Usuario> Estudiantes { get; }
    public IReadOnlyList<Usuario> Coordinadores { get; }
    public IReadOnlyList<JsonElement> Notas { get; }
    public IReadOnlyList<JsonElement> Asistencia { get; }

    public Datos(string carpeta)
    {
        var est = new List<Usuario>();
        var coo = new List<Usuario>();
        var notas = new List<JsonElement>();
        var asis = new List<JsonElement>();
        if (Directory.Exists(carpeta))
        {
            foreach (var archivo in Directory.GetFiles(carpeta, "*.json").OrderBy(f => f, StringComparer.Ordinal))
            {
                using var doc = JsonDocument.Parse(File.ReadAllText(archivo));
                if (doc.RootElement.ValueKind != JsonValueKind.Array) continue;
                foreach (var e in doc.RootElement.EnumerateArray())
                {
                    if (e.ValueKind != JsonValueKind.Object) continue;
                    var c = e.Clone();
                    if (Tiene(c, "estudianteId") && Tiene(c, "definitiva")) notas.Add(c);
                    else if (Tiene(c, "estudianteId") && Tiene(c, "inasistencias")) asis.Add(c);
                    else if (Tiene(c, "id") && Tiene(c, "programa"))
                    {
                        var esEstudiante = Tiene(c, "semestre");
                        var id = Texto(c, "id");
                        var programa = Texto(c, "programa");
                        if (string.IsNullOrWhiteSpace(id) || programa == null) continue;
                        var u = new Usuario(esEstudiante ? "estudiante" : "coordinador",
                            id, Texto(c, "nombre") ?? "", programa);
                        (esEstudiante ? est : coo).Add(u);
                    }
                }
            }
        }
        Estudiantes = est;
        Coordinadores = coo;
        Notas = notas;
        Asistencia = asis;
    }

    static bool Tiene(JsonElement e, string p) => e.TryGetProperty(p, out _);
    static string? Texto(JsonElement e, string p) =>
        e.TryGetProperty(p, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;

    public Usuario? BuscarUsuario(string rol, string id) =>
        (rol == "estudiante" ? Estudiantes : rol == "coordinador" ? Coordinadores : [])
            .FirstOrDefault(u => u.Id == id);
}

var app = builder.Build();

// Carga eager: un dato corrupto falla al arrancar, nunca convierte un 400 en 500.
app.Services.GetRequiredService<Reglamento>();
app.Services.GetRequiredService<Datos>();

app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));

app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg) =>
{
    static IResult Error(int codigo, string msg) => Results.Json(new { error = msg }, statusCode: codigo);

    JsonDocument doc;
    try { doc = await JsonDocument.ParseAsync(req.Body); }
    catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }

    using (doc)
    {
        var raiz = doc.RootElement;
        if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");

        if (!raiz.TryGetProperty("pregunta", out var p) || p.ValueKind != JsonValueKind.String
            || string.IsNullOrWhiteSpace(p.GetString()))
            return Error(400, "La pregunta es obligatoria.");
        if (p.GetString()!.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");

        if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
            return Error(400, "El usuario es obligatorio.");
        if (!u.TryGetProperty("rol", out var r) || r.ValueKind != JsonValueKind.String)
            return Error(400, "El rol es obligatorio.");
